const response = $input.item.json;
let publicaties = [];
if (response.content && Array.isArray(response.content)) {
  publicaties = response.content;
} else if (Array.isArray(response)) {
  publicaties = response;
}
if (publicaties.length === 0) {
  return { json: { aantalPublicaties: 0, publicaties: [], bericht: 'Geen nieuwe tenders gevonden' } };
}
// Deduplicate by publicatieId
const seen = new Set();
publicaties = publicaties.filter(p => {
  if (!p.publicatieId || seen.has(p.publicatieId)) return false;
  seen.add(p.publicatieId);
  return true;
});
return { json: { aantalPublicaties: publicaties.length, publicaties: publicaties } };

const item = $input.item.json;
const cpvCodes = [];
if (item.cpvCodes && Array.isArray(item.cpvCodes)) {
  item.cpvCodes.forEach(c => { if (c.code) cpvCodes.push(c.code.split('-')[0]); });
}
const trefwoorden = [item.trefwoord1, item.trefwoord2, item.trefwoord3].filter(Boolean).map(t => t.replace(/"/g, '')).join(', ');
const url = `https://www.tenderned.nl/aankondigingen/overzicht/${item.publicatieId}`;
return { json: { json_publicatieId: item.publicatieId, json_aanbestedingNaam: item.aanbestedingNaam || '', json_opdrachtgeverNaam: item.opdrachtgeverNaam || '', json_opdrachtBeschrijving: item.opdrachtBeschrijving || '', json_publicatieDatum: item.publicatieDatum || '', json_sluitingsDatum: item.sluitingsDatum || '', json_deadline_aanvragen: item.termijnVoorOntvangstVanAanvragen || item.termijnIndienenVragen || '', json_procedure: item.procedureCode?.omschrijving || '', json_typeOpdracht: item.typeOpdrachtCode?.omschrijving || '', json_trefwoorden: trefwoorden || '-', cpv_codes: cpvCodes, cpv_main: cpvCodes[0] || null, cpv_all_text: cpvCodes.join(', '), originalLink: url, originele_data_json: JSON.stringify(item) } };

const j = $input.item.json;
function parseDate(d) { if (!d) return null; try { return d.split('T')[0]; } catch(e) { return null; } }
return { json: { external_id: String(j.json_publicatieId || ''), naam: j.json_aanbestedingNaam || '', opdrachtgever: j.json_opdrachtgeverNaam || '', publicatie_datum: parseDate(j.json_publicatieDatum), sluiting_datum: parseDate(j.json_sluitingsDatum), cpv_codes: j.cpv_all_text || '', cpv_main: j.cpv_main || null, beschrijving: j.json_opdrachtBeschrijving || '', note: '', waarde: '', deadline_vragen: parseDate(j.json_deadline_aanvragen) || '', platform: 'TenderNed', url: j.originalLink || '', trefwoorden: j.json_trefwoorden || '', procedure: j.json_procedure || '', type_opdracht: j.json_typeOpdracht || '', raw_json: j.originele_data_json || '{}' } };

try {
  const carryCtxItem = $('Carry Context').first();
  const fitInput = $input.first();

  if (!carryCtxItem || !fitInput || carryCtxItem.json.error || fitInput.json.error) {
    const prepRaw = $('Prepare AI Input').first();
    const pi = prepRaw ? prepRaw.json : {};
    return { json: {
      external_id: pi.external_id || '',
      executive_summary: 'AI analysis failed - skipped',
      recommended_action: 'Monitor only',
      confidence_level: 'Low',
      recommended_products: JSON.stringify([]),
      fit_level: 'Low',
      fit_reasoning: '',
      open_questions: JSON.stringify([]),
      likely_competitive_context: '',
      key_requirements: JSON.stringify([]),
      possible_knockout_risks: JSON.stringify([]),
      commercial_relevance: '',
      what_is_being_bought: '',
      why_it_matters: '',
      priority_score: 0,
      status: 'analyzed',
      analyzed_at: new Date().toISOString(),
      score: pi.score || 0,
      label: pi.label || 'Monitor',
      score_breakdown: pi.score_breakdown || {},
      keyword_result: pi.keyword_result || '',
      keyword_matches: pi.keyword_matches || [],
      buyer_type_detected: pi.buyer_type_detected || '',
      red_flags: pi.red_flags || [],
      llm_relevance: pi.llm_relevance || '',
      llm_relevance_reason: (pi.llm_relevance_reason || '').substring(0, 300)
    }};
  }

  const carryCtx = carryCtxItem.json;
  const fitOutput = fitInput.json.output || {};
  const analysisOutput = carryCtx.analysis_output || {};

  const fitScore = { High: 3, Medium: 2, Low: 1 }[fitOutput.fit_level] || 1;
  const actionScore = { 'Pursue immediately': 4, 'Qualify further': 3, 'Monitor only': 2, 'No-bid': 1 }[analysisOutput.recommended_action] || 1;
  const priorityScore = fitScore * actionScore;

  // Real d1 from the AI fit verdict replaces the provisional constant; recompute score + label.
  // Hot requires BOTH strong product fit and good conditions - this is what gates Prompt C.
  const bd = Object.assign({}, carryCtx.score_breakdown || {});
  const d1Map = { High: 15, Medium: 8, Low: 2 };
  const d1New = d1Map[fitOutput.fit_level] !== undefined ? d1Map[fitOutput.fit_level] : 8;
  const oldD1 = typeof bd.d1 === 'number' ? bd.d1 : 15;
  bd.d1 = d1New;
  const finalScore = (carryCtx.score || 0) - oldD1 + d1New;
  const flags = carryCtx.red_flags || [];
  let finalLabel;
  if (flags.includes('deadline_passed')) {
    finalLabel = 'Disqualified';
  } else {
    finalLabel = finalScore >= 40 ? 'Warm' : finalScore >= 20 ? 'Cold' : 'Monitor';
    if (fitOutput.fit_level === 'High' && finalScore >= 50) finalLabel = 'Hot';
    if (flags.length > 0) {
      const ladder = ['Monitor', 'Cold', 'Warm', 'Hot'];
      finalLabel = ladder[Math.max(0, ladder.indexOf(finalLabel) - 1)];
    }
  }

  return { json: {
    external_id: carryCtx.external_id,
    executive_summary: analysisOutput.executive_summary || '',
    what_is_being_bought: analysisOutput.what_is_being_bought || '',
    why_it_matters: analysisOutput.why_it_matters || '',
    key_requirements: JSON.stringify(analysisOutput.key_requirements || []),
    possible_knockout_risks: JSON.stringify(analysisOutput.possible_knockout_risks || []),
    commercial_relevance: analysisOutput.commercial_relevance || '',
    recommended_action: (analysisOutput.recommended_action || '').substring(0, 50),
    confidence_level: (analysisOutput.confidence_level || '').substring(0, 20),
    recommended_products: JSON.stringify(fitOutput.recommended_products || []),
    fit_reasoning: fitOutput.fit_reasoning || '',
    fit_level: (fitOutput.fit_level || '').substring(0, 20),
    open_questions: JSON.stringify(fitOutput.open_questions || []),
    likely_competitive_context: fitOutput.likely_competitive_context || '',
    priority_score: priorityScore,
    status: 'analyzed',
    analyzed_at: new Date().toISOString(),
    score: finalScore,
    label: finalLabel,
    score_breakdown: bd,
    keyword_result: carryCtx.keyword_result || '',
    keyword_matches: carryCtx.keyword_matches || [],
    buyer_type_detected: carryCtx.buyer_type_detected || '',
    red_flags: carryCtx.red_flags || [],
    llm_relevance: carryCtx.llm_relevance || '',
    llm_relevance_reason: (carryCtx.llm_relevance_reason || '').substring(0, 300)
  }};
} catch(e) {
  const prepRaw = $('Prepare AI Input').first();
  const pi = prepRaw ? prepRaw.json : {};
  return { json: {
    external_id: pi.external_id || '',
    executive_summary: 'Analysis error: ' + e.message,
    recommended_action: 'Monitor only',
    confidence_level: 'Low',
    recommended_products: JSON.stringify([]),
    fit_level: 'Low',
    fit_reasoning: '',
    open_questions: JSON.stringify([]),
    likely_competitive_context: '',
    key_requirements: JSON.stringify([]),
    possible_knockout_risks: JSON.stringify([]),
    commercial_relevance: '',
    what_is_being_bought: '',
    why_it_matters: '',
    priority_score: 0,
    status: 'analyzed',
    analyzed_at: new Date().toISOString(),
    score: pi.score || 0,
    label: pi.label || 'Monitor',
    score_breakdown: pi.score_breakdown || {},
    keyword_result: pi.keyword_result || '',
    keyword_matches: pi.keyword_matches || [],
    buyer_type_detected: pi.buyer_type_detected || '',
    red_flags: pi.red_flags || [],
    llm_relevance: pi.llm_relevance || '',
    llm_relevance_reason: (pi.llm_relevance_reason || '').substring(0, 300)
  }};
}

const APP = 'https://cba-tender-intelligence.vercel.app';
const HOOK = 'https://deivyramos.app.n8n.cloud/webhook/tender-feedback';
const TOKEN = '74504437eb764a28b46debf9caf6463c';

const tenders = $('Read Analyzed Today').all().map(i => i.json).filter(r => r && r.id);
const deadlines = $input.all().map(i => i.json).filter(r => r && r.id);

if (tenders.length === 0 && deadlines.length === 0) return [];

const hot = tenders.filter(r => r.label === 'Hot');
const warm = tenders.filter(r => r.label === 'Warm');

function fbLinks(t) {
  const base = HOOK + '?id=' + t.id + '&t=' + TOKEN + '&v=';
  return '<div style="margin-top:6px;font-size:12px;color:#6b7280;">Relevant voor CBA? ' +
    '<a href="' + base + 'relevant" style="color:#16a34a;text-decoration:none;">&#128077; Ja</a> &nbsp;&middot;&nbsp; ' +
    '<a href="' + base + 'not_relevant" style="color:#dc2626;text-decoration:none;">&#128078; Nee</a></div>';
}

function formatTender(t) {
  const color = t.label === 'Hot' ? '#dc2626' : '#d97706';
  const appUrl = APP + '/tender/' + t.id;
  let products = '';
  try { products = JSON.parse(t.recommended_products || '[]').join(', '); } catch(e) { products = String(t.recommended_products || ''); }
  const flags = Array.isArray(t.red_flags) ? t.red_flags : [];
  const flagLine = flags.length ? '<br/><span style="color:#dc2626">Risico: ' + flags.join(', ') + '</span>' : '';
  const routeLine = (t.route_to_market && t.label === 'Hot')
    ? '<br/><strong style="color:#1d4ed8">Route: ' + t.route_to_market + (t.reseller_name ? ' (' + t.reseller_name + ')' : '') + '</strong>' +
      (t.route_first_action ? '<br/><em>Eerste stap: ' + t.route_first_action + '</em>' : '')
    : '';
  const bidPackLine = (t.label === 'Hot')
    ? '<br/><a href="' + appUrl + '" style="color:#1d4ed8;font-weight:bold;">&#128188; Bid pack klaar in de app &rarr;</a>'
    : '';
  return '<div style="margin-bottom:24px;border-left:4px solid ' + color + ';padding-left:12px;">' +
    '<a href="' + appUrl + '" style="font-weight:bold;color:#111827;font-size:15px;text-decoration:none;">' + (t.naam || '') + '</a> &mdash; ' + (t.opdrachtgever || '') + '<br/>' +
    '<em>Sluiting: ' + (t.sluiting_datum || 'onbekend') + ' | Score: ' + (t.score || 0) + ' | Label: ' + (t.label || '') + '</em><br/>' +
    '<em>Producten: ' + (products || 'n.v.t.') + ' | Fit: ' + (t.fit_level || 'n.v.t.') + '</em>' + flagLine + routeLine + '<br/>' +
    (t.executive_summary || '') + '<br/>' +
    (t.recommended_action ? '<strong>Actie: ' + t.recommended_action + '</strong>' : '') + bidPackLine + '<br/>' +
    '<a href="' + appUrl + '" style="color:#1d4ed8;">Open in de app &rarr;</a> &nbsp;&middot;&nbsp; ' +
    '<a href="' + (t.url || '') + '" style="color:#9ca3af;font-size:12px;">TenderNed</a>' +
    fbLinks(t) + '</div>';
}

const dateStr = new Date().toLocaleDateString('nl-NL');
let deadlineBlock = '';
if (deadlines.length) {
  const items = deadlines.map(d =>
    '<li style="margin-bottom:4px;"><a href="' + APP + '/tender/' + d.id + '" style="color:#92400e;font-weight:bold;">' + (d.naam || '') + '</a>' +
    ' &mdash; ' + (d.stage || '') + ' &mdash; sluit over ' + d.days_left + ' ' + (d.days_left === 1 ? 'dag' : 'dagen') + ' (' + d.sluiting_datum + ')</li>').join('');
  deadlineBlock = '<div style="background:#fef3c7;border-left:4px solid #d97706;padding:10px 14px;margin-bottom:20px;">' +
    '<strong>&#9203; Deadlines op het bid board</strong><ul style="margin:6px 0 0 0;padding-left:18px;">' + items + '</ul></div>';
}

const html = '<h2>CBA Tender Intelligence &mdash; ' + dateStr + '</h2>' +
  deadlineBlock +
  (tenders.length
    ? '<p><strong>' + tenders.length + ' relevante tenders</strong> | Hot: ' + hot.length + ' | Warm: ' + warm.length + '</p>' +
      (hot.length ? '<h3 style="color:#dc2626">Hot (' + hot.length + ')</h3>' + hot.map(formatTender).join('') : '') +
      (warm.length ? '<h3 style="color:#d97706">Warm (' + warm.length + ')</h3>' + warm.map(formatTender).join('') : '')
    : '<p>Geen nieuwe relevante tenders vandaag.</p>') +
  '<p style="margin-top:24px;"><a href="' + APP + '/dashboard" style="background:#1d4ed8;color:#fff;padding:8px 16px;border-radius:6px;text-decoration:none;">Open het dashboard &rarr;</a></p>';

const subjParts = [];
if (hot.length) subjParts.push(hot.length + ' Hot');
if (warm.length) subjParts.push(warm.length + ' Warm');
if (deadlines.length) subjParts.push(deadlines.length + ' deadline' + (deadlines.length > 1 ? 's' : ''));
const subject = 'Tender Intel ' + dateStr + (subjParts.length ? ' - ' + subjParts.join(', ') : '');
return [{ json: { subject, body: html } }];

const j = $input.item.json;
const text = [j.naam, j.beschrijving, j.trefwoorden].filter(Boolean).join(' ').toLowerCase();

const negKw = [
  'schoonmaak','schoonmaakdiensten','catering','fysieke beveiliging','bewaking',
  'bouw','verbouw','renovatie','sloopwerkzaamheden','groenvoorziening','groenonderhoud',
  'vervoer','transport','personeelsvervoer','inhuur personeel','uitzendkrachten',
  'thuiszorg','hulp bij huishouden','afvalverwerking','rioolbeheer','wegenbouw',
  'civieltechnisch','drukwerk','kantoorartikelen',
  'physical security','construction work','landscaping','staffing agency','waste management','road construction'
];

if (negKw.some(kw => text.includes(kw))) {
  return { json: { ...j, keyword_result: 'DISQUALIFY', keyword_matches: [], kw_negative_hit: true } };
}

const posKw = [
  'servicedesk','service desk','helpdesk','help desk','itsm','itil',
  'service management','servicemanagement','it service management','meldingenbeheer',
  'incidentbeheer','incident management','probleembeheer','wijzigingsbeheer',
  'change management','cmdb','configuration management database','kennisbank',
  'asset management','it asset management','contractbeheer','slm',
  'monitoring','monitoringtool','monitoring tool','netwerkmonitoring',
  'infrastructuurmonitoring','applicatiemonitoring','observability','alerting',
  'uptime','noc','apm','log management','event management','systeembeheer',
  'wachtwoordkluis','wachtwoordbeheer','wachtwoordmanager','password management','password manager',
  'privileged access management','pam','enterprise password vault','password vault',
  'bevoorrechte toegang','sessiebeheer','identity management','gebruikersbeheer',
  'active directory beheer','active directory audit','ad audit','toegangsbeheer','iam','siem',
  'patch management','patchbeheer','mdm','mobile device management','endpoint management','endpoint central',
  'netwerkbeheer','netwerk management','network management','netwerk monitoring',
  'it-beheer','it beheer','it operaties','it operations','itom',
  'kwetsbaarheidsbeheer','vulnerability management','remote monitoring','remote beheer',
  'apparaatbeheer','device management','zero trust','privileged account'
];

const matches = posKw.filter(kw => text.includes(kw));
const result = matches.length >= 2 ? 'PASS' : matches.length === 1 ? 'AMBIGUOUS' : 'DISQUALIFY';

return { json: { ...j, keyword_result: result, keyword_matches: matches, kw_negative_hit: false } };

const item = $input.item.json;
function norm(s) { return (s||'').toLowerCase(); }
const now = new Date();
const bd = {};
bd.d1 = 15;
let d2 = 2;
try {
  const raw = typeof item.raw_json === 'string' ? JSON.parse(item.raw_json) : (item.raw_json || {});
  const v = parseFloat(raw.raamovereenkomstWaarde || raw.opdrachtwaarde || raw.totaleWaarde || 0);
  if (v >= 500000) d2 = 20;
  else if (v >= 200000) d2 = 15;
  else if (v >= 100000) d2 = 10;
  else if (v >= 50000) d2 = 5;
} catch(e) {}
bd.d2 = d2;
const proc = norm(item.procedure);
bd.d3 = proc.includes('openbaar') ? 15 : proc.includes('versneld') ? 13 : proc.includes('niet-openbaar') ? 12 : proc.includes('onderhandeling') ? 10 : proc.includes('mini-competitie') ? 6 : 8;
const buyer = norm(item.opdrachtgever);
const authMap = [[['rijkswaterstaat','ministerie','belastingdienst','cibg','rvo'],'rijksoverheid',15],[['politie'],'politie',14],[['defensie'],'defensie',14],[['provincie'],'provincie',13],[['gemeente amsterdam','gemeente rotterdam','gemeente den haag','gemeente utrecht'],'grote gemeente',13],[['hogeschool','universiteit','mbo'],'onderwijs',12],[['ziekenhuis','umc'],'zorg',11],[['waterschap'],'waterschap',9],[['gemeente'],'gemeente',7]];
let d4 = 5, buyerType = 'overig';
for (const [keys, type, pts] of authMap) { if (keys.some(k => buyer.includes(k))) { d4 = pts; buyerType = type; break; } }
bd.d4 = d4;
const dlWeeks = item.sluiting_datum ? (new Date(item.sluiting_datum) - now) / 6048e5 : null;
bd.d5 = dlWeeks === null ? 5 : dlWeeks >= 6 ? 10 : dlWeeks >= 3 ? 7 : dlWeeks >= 2 ? 4 : dlWeeks >= 0 ? 1 : 0;
const hrs = item.scraped_at ? (now - new Date(item.scraped_at)) / 36e5 : null;
bd.d6 = !hrs || hrs <= 48 ? 5 : hrs <= 120 ? 3 : 1;
bd.d7 = 0;
const rawScore = bd.d1+bd.d2+bd.d3+bd.d4+bd.d5+bd.d6+bd.d7;
const flags = [];
const tn = norm(item.naam);
if (dlWeeks !== null && dlWeeks < 1.5) flags.push('deadline_too_short');
if (dlWeeks !== null && dlWeeks < 0) flags.push('deadline_passed');
if ((tn.includes('verlenging')||tn.includes(' optie '))&&!tn.includes('nieuw')) flags.push('renewal_likely');
const rawLabel = rawScore >= 70 ? 'Hot' : rawScore >= 45 ? 'Warm' : rawScore >= 20 ? 'Cold' : 'Monitor';
const ladder = ['Monitor','Cold','Warm','Hot'];
let label = flags.length > 0 ? (ladder[Math.max(0,ladder.indexOf(rawLabel)-1)]) : rawLabel;
if (flags.includes('deadline_passed')) label = 'Disqualified';
return { json: { ...item, score: rawScore, label, score_breakdown: bd, red_flags: flags, buyer_type_detected: buyerType } };

const j = $input.item.json;
function s(v) { if (v===null||v===undefined) return 'NULL'; return "'" + String(v).replace(/'/g,"''") + "'"; }
function arrStr(a) { if (!a||a.length===0) return "ARRAY[]::text[]"; return "ARRAY[" + a.map(x=>s(x)).join(',') + "]::text[]"; }
const sql = ["UPDATE tenders_scraped SET","  status = 'analyzed',","  analyzed_at = NOW(),","  score = "+(j.score||0)+",","  label = "+s(j.label)+",","  score_breakdown = "+s(JSON.stringify(j.score_breakdown||{}))+ "::jsonb,","  keyword_result = "+s(j.keyword_result)+",","  keyword_matches = "+arrStr(j.keyword_matches)+",","  buyer_type_detected = "+s(j.buyer_type_detected)+",","  red_flags = "+arrStr(j.red_flags),"WHERE id = "+j.id].join('\n');
return { json: { ...j, _cold_sql: sql } };

const src = { ...$('Build Prompt A').item.json };
delete src._oai_body;
try {
  const choices = $input.item.json.choices;
  const content = choices && choices[0] && choices[0].message && choices[0].message.content;
  const r = JSON.parse(content);
  return { json: { ...src, llm_relevance: r.relevant ? 'RELEVANT' : 'NOT_RELEVANT', llm_relevance_reason: (r.reason||'').substring(0,300) } };
} catch(e) {
  return { json: { ...src, llm_relevance: 'RELEVANT', llm_relevance_reason: 'parse_error: '+e.message } };
}

const httpResp = $input.item.json;
const buildItem = $('Build Prompt C').item.json;
let route_to_market = null, reseller_name = null, route_reasoning = null, route_first_action = null, reseller_outreach_draft = null;
try {
  const raw = httpResp.choices[0].message.content;
  const clean = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const parsed = JSON.parse(clean);
  route_to_market = parsed.route || null;
  reseller_name = (parsed.reseller_name === 'null' || !parsed.reseller_name) ? null : parsed.reseller_name;
  route_reasoning = parsed.reasoning || null;
  route_first_action = parsed.first_action || null;
  reseller_outreach_draft = (parsed.reseller_outreach_draft === 'null' || !parsed.reseller_outreach_draft) ? null : parsed.reseller_outreach_draft;
} catch(e) {
  route_reasoning = 'Parse error: ' + e.message;
}
const { _oai_body_c, ...rest } = buildItem;
return { json: { ...rest, route_to_market, reseller_name, route_reasoning, route_first_action, reseller_outreach_draft } };

const tender = { ...$('Score Tender').item.json };
const a = $input.item.json || {};
let adj = parseFloat(a.total_adjustment);
if (!isFinite(adj)) adj = 0;
const applied = Array.isArray(a.applied) ? a.applied : [];
const score = (tender.score || 0) + adj;
const flags = tender.red_flags || [];
const rawLabel = score >= 70 ? 'Hot' : score >= 45 ? 'Warm' : score >= 20 ? 'Cold' : 'Monitor';
const ladder = ['Monitor','Cold','Warm','Hot'];
let label = flags.length > 0 ? ladder[Math.max(0, ladder.indexOf(rawLabel)-1)] : rawLabel;
if (flags.includes('deadline_passed')) label = 'Disqualified';
return { json: { ...tender, score, label, score_adjustment: adj, adjustments_applied: applied } };

const pi = $('Prepare AI Input').item.json;
function esc(s) { return String(s).replace(/'/g, "''"); }
let sql = 'SELECT 1';
try {
  const content = JSON.parse($input.item.json.choices[0].message.content);
  const tid = parseInt(pi.id, 10);
  if (Number.isInteger(tid) && content && typeof content === 'object') {
    sql = "INSERT INTO bid_packs (tender_id, content, model) VALUES (" + tid + ", '" + esc(JSON.stringify(content)) + "'::jsonb, 'gpt-4o') " +
      "ON CONFLICT (tender_id) DO UPDATE SET content = EXCLUDED.content, model = EXCLUDED.model, created_at = now() RETURNING tender_id";
  }
} catch (e) {}
return { json: { _bidpack_sql: sql } };

const resp = $input.item.json || {};
const docs = Array.isArray(resp.documenten) ? resp.documenten : [];
const wanted = docs.filter(d =>
  d && d.typeDocument && d.typeDocument.code === 'pdf' &&
  d.publicatieCategorie && ['DOC','NVI','ANK'].includes(d.publicatieCategorie.code) &&
  (d.grootte || 0) < 15000000 &&
  d.links && d.links.download && d.links.download.href
);
const order = { DOC: 0, NVI: 1, ANK: 2 };
wanted.sort((a, b) => order[a.publicatieCategorie.code] - order[b.publicatieCategorie.code]);
const picked = wanted.slice(0, 4);
if (picked.length === 0) {
  let extern = null;
  try {
    const raw = $('Apply Learned Adjustment').item.json.raw_json;
    const parsed = typeof raw === 'string' ? JSON.parse(raw) : (raw || {});
    extern = parsed.urlTsenderWebsite || parsed.urlDigitaalSysteem || null;
  } catch (e) {}
  return [{ json: { _no_docs: true, _extern: extern } }];
}
